package dev.votex.addons;

import com.google.gson.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Official response-shape fixtures. No credentials or authenticated network success are assumed. */
class CurseForgeRulesTest {
 private static JsonObject project(){return JsonParser.parseString("{\"id\":238222,\"gameId\":432,\"classId\":6,\"name\":\"Fixture Mod\",\"summary\":\"Fixture only\",\"downloadCount\":1234,\"allowModDistribution\":true,\"logo\":{\"thumbnailUrl\":\"https://media.forgecdn.net/avatars/thumbnails/1/2/256/256/icon.png\"},\"links\":{\"websiteUrl\":\"https://www.curseforge.com/minecraft/mc-mods/fixture\"}}").getAsJsonObject();}
 private static JsonObject file(long id){var f=JsonParser.parseString("{\"id\":1,\"modId\":238222,\"gameId\":432,\"isAvailable\":true,\"displayName\":\"Fixture 1.0\",\"fileName\":\"fixture.jar\",\"releaseType\":1,\"fileLength\":3,\"fileDate\":\"2026-10-20T00:00:00Z\",\"hashes\":[{\"value\":\"a9993e364706816aba3e25717850c26c9cd0d89d\",\"algo\":1}],\"downloadUrl\":\"https://edge.forgecdn.net/files/1234/567/fixture.jar\",\"gameVersions\":[\"26.2\",\"Fabric\"],\"dependencies\":[]}").getAsJsonObject();f.addProperty("id",id);return f;}
 private static JsonObject response(JsonObject... files){var r=new JsonObject();var data=new JsonArray();for(var f:files)data.add(f);r.add("data",data);return r;}
 @Test void officialRoutesEncodeQueriesAndEnforcePagination(){String route=CurseForgeRules.searchRoute("a & ä","mod",99999,20);assertTrue(route.contains("gameId=432"));assertTrue(route.contains("modLoaderType=4"));assertTrue(route.contains("searchFilter=a+%26+%C3%A4"));assertTrue(route.contains("index=9999&pageSize=1"));assertEquals("api.curseforge.com",CurseForgeRules.api(route).getHost());assertFalse(CurseForgeRules.filesRoute(22,"shader").contains("modLoaderType"));assertEquals(12,CurseForgeRules.classId("resourcepack"));assertThrows(IllegalArgumentException.class,()->CurseForgeRules.classId("modpack"));}
 @Test void endpointAndCdnScopesRejectCredentialLeaksAndUntrustedRedirects(){assertNotNull(CurseForgeRules.api("mods/123/files/456/download-url"));for(String value:List.of("https://evil.test/x","../mods/1","mods/1#x","mods/1/../../search","mods/1?x=https://evil.test"))assertThrows(IllegalArgumentException.class,()->CurseForgeRules.api(value));for(String value:List.of("http://edge.forgecdn.net/files/1/2/a.jar","https://edge.forgecdn.net.evil.test/files/1/2/a.jar","https://user@edge.forgecdn.net/files/1/2/a.jar","https://edge.forgecdn.net/files/1/2/a.jar?apiKey=secret","https://cdn.modrinth.com/files/1/2/a.jar","https://edge.forgecdn.net/files/1/2/../a.jar","https://edge.forgecdn.net:443/files/1/2/a.jar"))assertThrows(IllegalArgumentException.class,()->CurseForgeRules.download(value));assertNotNull(CurseForgeRules.download("https://mediafilez.forgecdn.net/files/1/2/a.jar"));assertNotNull(CurseForgeRules.icon("https://media.forgecdn.net/avatars/thumbnails/1/2/64/64/test.png"));assertThrows(IllegalArgumentException.class,()->CurseForgeRules.icon("https://media.forgecdn.net/files/1/2/a.jar"));}
 @Test void parsesRealSchemaWithoutConvertingDistributionDenialsIntoDownloads(){var raw=project();raw.addProperty("allowModDistribution",false);var body=response(raw);body.add("pagination",JsonParser.parseString("{\"totalCount\":1}"));var search=CurseForgeRules.search(body,"mod",0);assertEquals(238222,search.projects().getFirst().id());assertEquals(Boolean.FALSE,search.projects().getFirst().distributionAllowed());assertThrows(IllegalArgumentException.class,()->CurseForgeRules.distribution(search.projects().getFirst()));raw.addProperty("gameId",123);assertThrows(IllegalArgumentException.class,()->CurseForgeRules.project(raw));}
 @Test void selectsCompatibleReleaseBeforeNewerAlphaAndRejectsForge(){var alpha=file(8);alpha.addProperty("releaseType",3);alpha.addProperty("fileDate","2026-10-21T00:00:00Z");var forge=file(9);forge.add("gameVersions",JsonParser.parseString("[\"26.2\",\"Forge\"]"));var selected=CurseForgeRules.select(response(alpha,forge,file(7)),CurseForgeRules.project(project()));assertEquals(7,selected.id());assertEquals("fixture.jar",selected.name());}
 @Test void requiresCorrectGameFileIdentityAvailabilityAndFreeClientContent(){var p=CurseForgeRules.project(project());for(String property:List.of("isServerPack","isEarlyAccessContent")){var f=file(1);f.addProperty(property,true);assertFalse(CurseForgeRules.compatible(f,p));}var f=file(1);f.addProperty("isAvailable",false);assertFalse(CurseForgeRules.compatible(f,p));f=file(1);f.addProperty("modId",999);assertFalse(CurseForgeRules.compatible(f,p));f=file(1);f.add("gameVersions",JsonParser.parseString("[\"1.21.11\",\"Fabric\"]"));assertFalse(CurseForgeRules.compatible(f,p));}
 @Test void requiresSha1AndSizeBoundInsteadOfTrustingMurmurFingerprint(){var p=CurseForgeRules.project(project());var f=file(1);f.addProperty("fileFingerprint",12345678);f.add("hashes",JsonParser.parseString("[{\"value\":\"900150983cd24fb0d6963f7d28e17f72\",\"algo\":2}]"));assertThrows(IllegalArgumentException.class,()->CurseForgeRules.file(f,p));var oversized=file(2);oversized.addProperty("fileLength",AddonRules.MAX_FILE+1);assertThrows(IllegalArgumentException.class,()->CurseForgeRules.file(oversized,p));}
 @Test void distinguishesRequiredOptionalEmbeddedAndIncompatibleRelations(){var f=file(1);f.add("dependencies",JsonParser.parseString("[{\"modId\":100,\"relationType\":3},{\"modId\":100,\"relationType\":3},{\"modId\":101,\"relationType\":2},{\"modId\":102,\"relationType\":1},{\"modId\":103,\"relationType\":5}]"));var parsed=CurseForgeRules.file(f,CurseForgeRules.project(project()));assertEquals(Set.of(100L),parsed.required());assertEquals(Set.of(103L),parsed.incompatible());}
 @Test void verifiesDownloadedBytesAndRejectsHashOrLengthChanges(){var parsed=CurseForgeRules.file(file(1),CurseForgeRules.project(project()));CurseForgeRules.verify(parsed,"abc".getBytes(StandardCharsets.UTF_8));assertThrows(IllegalArgumentException.class,()->CurseForgeRules.verify(parsed,"abd".getBytes(StandardCharsets.UTF_8)));assertThrows(IllegalArgumentException.class,()->CurseForgeRules.verify(parsed,new byte[4]));}
 @Test void nullDistributionDoesNotInventPermissionOrAFileUrl(){var raw=project();raw.add("allowModDistribution",JsonNull.INSTANCE);var p=CurseForgeRules.project(raw);assertNull(p.distributionAllowed());var f=file(1);f.add("downloadUrl",JsonNull.INSTANCE);assertEquals("",CurseForgeRules.file(f,p).url());}
 @Test void rejectsMalformedIdsKeysAndFractionalApiNumbers(){for(String value:List.of("0","-1","1/2","4294967296","abc"))assertThrows(IllegalArgumentException.class,()->CurseForgeRules.id(value));assertTrue(CurseForgeRules.validKey("fixture-only-key"));assertFalse(CurseForgeRules.validKey(""));assertFalse(CurseForgeRules.validKey("fixture\nkey"));var raw=project();raw.addProperty("id",2.5);assertThrows(IllegalArgumentException.class,()->CurseForgeRules.project(raw));}
}
